module resistor_network (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [63:0] a_in,\n    input wire [63:0] b_in,\n    output reg [63:0] result,\n    output reg done\n);\n    // State declarations\n    localparam IDLE = 1'b0;\n    localparam COMPUTE = 1'b1;\n    \n    reg state;\n    reg [63:0] a, b, count;\n    \n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            a <= 64'd0;\n            b <= 64'd0;\n            count <= 64'd0;\n            result <= 64'd0;\n            done <= 1'b0;\n        end else begin\n            case(state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        a <= a_in;\n                        b <= b_in;\n                        count <= 64'd0;\n                        state <= COMPUTE;\n                    end\n                end\n                \n                COMPUTE: begin\n                    if (b == 64'd0) begin\n                        result <= count;\n                        done <= 1'b1;\n                        state <= IDLE;\n                    end else begin\n                        count <= count + (a / b);\n                        a <= b;\n                        b <= a % b;\n                    end\n                end\n                \n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule